                src={item.image}
                alt=""
                className="size-10 shrink-0 rounded-md border object-cover"
              />
            ) : (
              <div className="flex size-10 shrink-0 items-center justify-center rounded-md border border-dashed bg-muted/40 text-muted-foreground">
                <Package2 className="size-4 opacity-60" aria-hidden />
              </div>
            )}
            <div className="min-w-0">
              <p className="line-clamp-2 text-sm font-semibold leading-snug">
                {item.name}
              </p>
              <p className="font-mono text-xs text-muted-foreground">
                {item.sku}
              </p>
            </div>
          </Link>
        );
      },
    },
    {
      id: "quantity",
      header: "Số lượng",
      enableColumnFilter: false,
      enableSorting: false,
      meta: { disableColumnFilter: true },
      cell: ({ row }) => {
        const unit =
          row.original.unitLabel?.trim() || row.original.unitType;
        return (
          <Badge variant="outline" className="font-normal tabular-nums">
            {row.original.quantity.toLocaleString("vi-VN")} × {unit}
          </Badge>
        );
      },
    },
    {
      accessorKey: "unitPrice",
      header: "Đơn giá",
      enableColumnFilter: false,
      enableSorting: false,
      meta: { disableColumnFilter: true },
      cell: ({ row }) => {
        const item = row.original;
        const hasDiscount =
          item.listUnitPrice != null && item.listUnitPrice > item.unitPrice;
        return (
          <div className="text-xs tabular-nums">
            {hasDiscount ? (
              <p className="text-muted-foreground line-through">
                {formatVND(item.listUnitPrice!)}
              </p>
            ) : null}
            <p className="font-semibold">{formatVND(item.unitPrice)}</p>
          </div>
        );
      },
    },
    {
      accessorKey: "totalPrice",
      header: "Thành tiền",
      enableColumnFilter: false,
      enableSorting: false,
      meta: { disableColumnFilter: true },
      cell: ({ row }) => (
        <span className="font-bold tabular-nums text-primary">
          {formatVND(row.original.totalPrice)}
        </span>
      ),
    },
    defineDataTableActionsColumn<StoreOrderItemRow>({
      cell: ({ row }) => (
        <StoreOrderItemRowActions
          item={row.original}
          handlers={actionHandlers}
        />
      ),
    }),
  ];
}

"use client";

import { useMemo } from "react";
import { AdminDataTable } from "@ui/components/data-table";
import type { Order } from "@/lib/api";
import { getStoreOrderItemColumns } from "./store-order-items-columns";
import type { StoreOrderItemRowActionHandlers } from "./store-order-item-row-actions";
import { mapStoreOrderItemRows, type StoreOrderItemRow } from "./types";

export function StoreOrderItemsTable({
  orderId,
  items,
  actionHandlers,
}: {
  orderId: string;
  items?: Order["items"];
  actionHandlers: StoreOrderItemRowActionHandlers;
}) {
  const rows = useMemo(
    () => mapStoreOrderItemRows(orderId, items),
    [items, orderId],
  );

  const columns = useMemo(
    () => getStoreOrderItemColumns({ actionHandlers }),
    [actionHandlers],
  );

  if (rows.length === 0) {
    return (
      <p className="py-2 text-center text-sm text-muted-foreground">
        Không có sản phẩm trong đơn.
      </p>
    );
  }

  return (
    <AdminDataTable<StoreOrderItemRow>
      embedded
      tableScope={`store-order-${orderId}-items`}
      data={rows}
      columns={columns}
      getRowId={(row) => row.id}
      showTableToolbar={false}
      showColumnFilters={false}
      showTableColumnPicker={false}
      showIndexColumn
      indexColumnLabel="#"
      stickyTableHeader={false}
      horizontalScrollButtons={false}
      emptyLabel="Không có sản phẩm."
    />
  );
}

"use client";

import { cn } from "@ui/lib/utils";
import type { OrderStatus } from "@/lib/api";

const STEPS = ["Đặt", "Giao", "Xong"] as const;

function stepIndex(status: OrderStatus): number {
  if (status === "delivered") return 2;
  if (status === "cancelled") return -1;
  if (status === "shipped" || status === "confirmed") return 1;
  return 0;
}

export function StoreOrderProgressCell({ status }: { status: OrderStatus }) {
  const active = stepIndex(status);

  if (status === "cancelled") {
    return (
      <span className="inline-flex items-center rounded-full bg-destructive/10 px-2.5 py-1 text-[11px] font-semibold text-destructive">
        Đã hủy
      </span>
    );
  }

  return (
    <div className="flex min-w-[7.5rem] items-center gap-1">
      {STEPS.map((label, index) => {
        const done = active >= index;
        const current = active === index;
        return (
          <div key={label} className="flex flex-1 flex-col items-center gap-1">
            <div
              className={cn(
                "h-1.5 w-full rounded-full transition-colors",
                done ? "bg-primary" : "bg-muted",
                current && "ring-2 ring-primary/25",
              )}
            />
            <span
              className={cn(
                "text-[10px] font-medium leading-none",
                done ? "text-primary" : "text-muted-foreground",
              )}
            >
              {label}
            </span>
          </div>
        );
      })}
    </div>
  );
}

"use client";

import {
  Copy,
  ExternalLink,
  Headphones,
  Package,
  ShoppingCart,
  Eye,
} from "lucide-react";
import {
  DataTableRowActionsMenu,
  TABLE_ACTIONS_COLUMN_META,
  type DataTableRowActionItem,
} from "@ui/components/data-table";
import {
  ORDER_STATUS_LABELS,
  StoreOrderStatusBadge,
} from "@ui/components/product";
import { catalogProductHref } from "@workspace/api-client";
import type { StoreOrderRow } from "./types";

export type StoreOrderRowActionHandlers = {
  onViewDetail: (order: StoreOrderRow) => void;
  onReorder: (order: StoreOrderRow) => void | Promise<void>;
  onCopyCode: (order: StoreOrderRow) => void | Promise<void>;
  onCopySummary: (order: StoreOrderRow) => void | Promise<void>;
  onContactSupport: (order: StoreOrderRow) => void;
  busyOrderId?: string | null;
};

export function StoreOrderRowActions({
  order,
  handlers,
}: {
  order: StoreOrderRow;
  handlers: StoreOrderRowActionHandlers;
}) {
  const firstItem = order.items?.[0];
  const canReorder = order.status !== "cancelled";

  const actions: DataTableRowActionItem[] = [
    {
      key: "view",
      label: "Xem chi tiết",
      hint: "Mở trang theo dõi đơn đầy đủ",
      onClick: () => handlers.onViewDetail(order),
      icon: <Eye />,
      group: "primary",
    },
    {
      key: "reorder",
      label: canReorder ? "Mua lại vào giỏ" : "Thử đặt lại",
      hint: canReorder
        ? "Thêm toàn bộ dòng hàng vào giỏ hiện tại"
        : "Đơn đã hủy — vẫn có thể thử thêm SP còn bán",
      onClick: () => handlers.onReorder(order),
      icon: <ShoppingCart />,
      group: "primary",
      disabled: !order.items?.length,
    },
    {
      key: "copy-code",
      label: "Sao chép mã đơn",
      hint: order.orderNumber,
      onClick: () => handlers.onCopyCode(order),
      icon: <Copy />,
      group: "status",
      confirm: false,
    },
    {
      key: "copy-summary",
      label: "Sao chép tóm tắt",
      hint: "Mã, trạng thái, tổng tiền và danh sách SP",
      onClick: () => handlers.onCopySummary(order),
      icon: <Copy />,
      group: "status",
      confirm: false,
    },
    {
      key: "support",
      label: "Liên hệ hỗ trợ",
      hint: "Mở trang hỗ trợ với mã đơn",
      onClick: () => handlers.onContactSupport(order),
      icon: <Headphones />,
      group: "status",
      confirm: false,
    },
  ];

  if (firstItem?.productId) {
    actions.push({
      key: "open-product",
      label: "Xem SP đầu tiên",
      hint: firstItem.name,
      onClick: () => {
        window.open(catalogProductHref(firstItem.productId), "_blank", "noopener");
      },
      icon: <Package />,
      group: "status",
      confirm: false,
    });
  }

  actions.push({
    key: "open-detail-tab",
    label: "Mở tab mới",
    hint: "Xem chi tiết ở tab riêng",
    onClick: () => {
      window.open(`/store/orders/${order.id}`, "_blank", "noopener");
    },
    icon: <ExternalLink />,
    group: "status",
    confirm: false,
  });

  return (
    <DataTableRowActionsMenu
      actions={actions}
      busy={handlers.busyOrderId === order.id}
      autoConfirmDangerousActions={false}
      triggerLabel={`Thao tác đơn ${order.orderNumber}`}
      groups={{
        primary: { label: "Thao tác nhanh", sublabel: false },
        status: {
          label: "Tiện ích",
          sublabel: true,
          header: (
            <div className="flex flex-wrap items-center gap-1.5 px-1 pb-1">
              <StoreOrderStatusBadge status={order.status} />
              <span className="font-mono text-[11px] text-muted-foreground">
                {order.orderNumber}
              </span>
              <span className="text-[11px] text-muted-foreground">
                {ORDER_STATUS_LABELS[order.status]}
              </span>
            </div>
          ),
        },
      }}
    />
  );
}

export const storeOrderActionsColumnMeta = {
  ...TABLE_ACTIONS_COLUMN_META,
  className: `${TABLE_ACTIONS_COLUMN_META.className} sticky right-0 z-[10] bg-background/95 backdrop-blur-sm`,
};

import type { LucideIcon } from "lucide-react";
import {
  CircleCheckBig,
  Layers,
  OctagonX,
  Truck,
} from "lucide-react";
import type { OrderStatus } from "@/lib/api";

export type StoreOrderStatusGroup =
  | "all"
  | "shipping"
  | "completed"
  | "cancelled";

export type StoreOrderStatusGroupOption = {
  key: StoreOrderStatusGroup;
  label: string;
  shortLabel: string;
  icon: LucideIcon;
  tone: string;
};

export const STORE_ORDER_STATUS_GROUPS: StoreOrderStatusGroupOption[] = [
  {
    key: "all",
    label: "Tất cả đơn",
    shortLabel: "Tất cả",
    icon: Layers,
    tone: "text-foreground bg-muted",
  },
  {
    key: "shipping",
    label: "Đang xử lý / giao",
    shortLabel: "Đang giao",
    icon: Truck,
    tone: "text-primary bg-primary/10",
  },
  {
    key: "completed",
    label: "Đã giao thành công",
    shortLabel: "Đã giao",
    icon: CircleCheckBig,
    tone: "text-success bg-success/15",
  },
  {
    key: "cancelled",
    label: "Đã hủy",
    shortLabel: "Đã hủy",
    icon: OctagonX,
    tone: "text-destructive bg-destructive/10",
  },
];

export function toStoreOrderStatusGroup(
  status: OrderStatus,
): Exclude<StoreOrderStatusGroup, "all"> {
  if (status === "delivered") return "completed";
  if (status === "cancelled") return "cancelled";
  return "shipping";
}

export function matchesStoreOrderStatusGroup(
  status: OrderStatus,
  group: StoreOrderStatusGroup,
): boolean {
  if (group === "all") return true;
  return toStoreOrderStatusGroup(status) === group;
}

"use client";

import { Button } from "@ui/components/button";
import { Card, CardContent } from "@ui/components/card";
import { cn } from "@ui/lib/utils";
import type { OrderStatus } from "@/lib/api";
import {
  STORE_ORDER_STATUS_GROUPS,
  matchesStoreOrderStatusGroup,
  type StoreOrderStatusGroup,
} from "./store-order-status-groups";
import type { StoreOrderRow } from "./types";

export function StoreOrdersStatCards({
  orders,
  activeGroup,
  onGroupChange,
}: {
  orders: StoreOrderRow[];
  activeGroup: StoreOrderStatusGroup;
  onGroupChange: (group: StoreOrderStatusGroup) => void;
}) {
  const counts = STORE_ORDER_STATUS_GROUPS.reduce(
    (acc, option) => {
      if (option.key === "all") {
        acc[option.key] = orders.length;
        return acc;
      }
      acc[option.key] = orders.filter((order) =>
        matchesStoreOrderStatusGroup(order.status, option.key),
      ).length;
      return acc;
    },
    {} as Record<StoreOrderStatusGroup, number>,
  );

  return (
    <div className="grid grid-cols-1 gap-3 sm:grid-cols-2 xl:grid-cols-4">
      {STORE_ORDER_STATUS_GROUPS.map((option) => {
        const active = activeGroup === option.key;
        const Icon = option.icon;
        return (
          <Button
            key={option.key}
            type="button"
            variant="ghost"
            onClick={() => onGroupChange(option.key)}
            className="h-auto w-full whitespace-normal p-0 text-left font-normal text-foreground shadow-none hover:bg-transparent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2"
          >
            <Card
              className={cn(
                "h-full w-full cursor-pointer border-outline-variant bg-background transition-all",
                active
                  ? "border-primary shadow-md ring-1 ring-primary/20"
                  : "hover:border-primary/40 hover:shadow-sm",
              )}
            >
              <CardContent className="flex items-center justify-between gap-3 p-4 sm:p-5">
                <div className="min-w-0">
                  <p className="text-sm text-muted-foreground">
                    {option.shortLabel}
                  </p>
                  <p className="mt-1 text-3xl font-black tabular-nums text-foreground">
                    {counts[option.key]}
                  </p>
                  <p className="mt-1 line-clamp-1 text-xs text-muted-foreground">
                    {option.label}
                  </p>
                </div>
                <div
                  className={cn(
                    "flex size-11 shrink-0 items-center justify-center rounded-xl sm:size-12",
                    option.tone,
                  )}
                >
                  <Icon className="size-5 sm:size-6" aria-hidden />
                </div>
              </CardContent>
            </Card>
          </Button>
        );
      })}
    </div>
  );
}

export function countOrdersByStatus(
  orders: StoreOrderRow[],
  status: OrderStatus,
): number {
  return orders.filter((order) => order.status === status).length;
}

