                placeholder="Nhập mật khẩu hiện tại"
                className={PROFILE_FIELD_CLASS}
              />
            </FieldContent>
          </Field>
          <Field>
            <FieldLabel htmlFor="store-new-pw">Mật khẩu mới</FieldLabel>
            <FieldContent>
              <Input
                id="store-new-pw"
                type="password"
                autoComplete="new-password"
                value={newPassword}
                onChange={(e) => onNewPasswordChange(e.target.value)}
                placeholder="Tối thiểu 6 ký tự"
                className={PROFILE_FIELD_CLASS}
              />
            </FieldContent>
          </Field>
          <Field>
            <FieldLabel htmlFor="store-confirm-pw">
              Nhập lại mật khẩu mới
            </FieldLabel>
            <FieldContent>
              <Input
                id="store-confirm-pw"
                type="password"
                autoComplete="new-password"
                value={confirmPassword}
                onChange={(e) => onConfirmPasswordChange(e.target.value)}
                placeholder="Nhập lại mật khẩu mới"
                className={PROFILE_FIELD_CLASS}
              />
            </FieldContent>
          </Field>
          <div className={PROFILE_ACTION_BAR_CLASS}>
            <Button
              type="button"
              variant="secondary"
              className="min-w-full rounded-lg sm:min-w-40"
              onClick={onChangePassword}
              disabled={changingPassword}
            >
              {changingPassword ? (
                <Loader2 className="size-4 animate-spin" />
              ) : (
                <KeyRound className="size-4" />
              )}
              <span className="ml-2">Đổi mật khẩu</span>
            </Button>
          </div>
        </FieldSetContent>
      </FieldSet>
    </div>
  );
}

