"use client";

import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import { useMemo, useState } from "react";
import {
  Store,
  ShoppingCart,
  Package,
  Headphones,
  Box,
  ShieldCheck,
  Bell,
  UserCircle,
  ChevronDown,
  LogOut,
  User,
  Menu,
} from "lucide-react";
import { CartCountBadge } from "@ui/components/product";
import { useCart, cartStore } from "@/hooks/use-cart";
import { resetCartHydration } from "@/lib/cart-sync";
import { ThemeToggle } from "@ui/components/theme-toggle";
import { TextSizeToggle } from "@ui/components/text-size-toggle";
import { Separator } from "@ui/components/separator";
import { Button } from "@ui/components/button";
import { Heading, Text } from "@ui/components/typography";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@ui/components/dropdown-menu";
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
} from "@ui/components/sheet";
import { useSession } from "@/hooks/use-session";
import { useOpenCartDrawer } from "@/components/shared/cart-drawer";

export function Header() {
  const isDevelopment = process.env.NODE_ENV === "development";
  const pathname = usePathname();
  const router = useRouter();
  const session = useSession();
  const { itemCount } = useCart();
  const openCart = useOpenCartDrawer();
  const [mobileNavOpen, setMobileNavOpen] = useState(false);

  const nav = useMemo(() => {
    const items: { href: string; label: string; icon: typeof ShoppingCart }[] = [
      { href: "/catalog", label: "Danh mục sỉ", icon: ShoppingCart },
    ];
    items.push({ href: "/support", label: "Hỗ trợ", icon: Headphones });
    if (isDevelopment) {
      items.push({ href: "/graph", label: "Sơ đồ hệ thống", icon: Box });
    }
    return items;
  }, [isDevelopment]);

  const profileHref = "/store/profile";

  const handleLogout = () => {
    resetCartHydration();
    localStorage.removeItem("storesync_session");
    cartStore.clear();
    window.dispatchEvent(new Event("storesync-session"));
    router.push("/login");
  };

  return (
    <header className="sticky top-0 z-50 w-full border-b border-outline-variant bg-background text-foreground shadow-level-1 dark:bg-card dark:text-card-foreground">
      <div className="mx-auto flex h-16 max-w-full items-center gap-2 px-4 sm:px-6">
        {/* Brand */}
        <Link href="/" className="flex items-center gap-2 group min-w-0 shrink">
          <div className="bg-primary/10 p-1.5 rounded-lg transition-colors group-hover:bg-primary/20 shrink-0">
            <Store className="size-6 text-primary" />
          </div>
          <Heading as="span" size="title" className="text-primary tracking-tight truncate max-w-[9rem] sm:max-w-none">Hub B2B</Heading>
        </Link>

        <div className="ml-auto flex items-center gap-1 md:hidden">
          <Button
            type="button"
            variant="ghost"
            size="icon"
            onClick={openCart}
            aria-label={`Giỏ hàng${itemCount > 0 ? `, ${itemCount} loại` : ""}`}
            className="relative inline-flex size-10 items-center justify-center rounded-lg text-muted-foreground transition-colors hover:bg-muted hover:text-primary"
          >
            <ShoppingCart className="size-5" />
            <CartCountBadge
              count={itemCount}
              className="-right-0.5 -top-0.5 h-4 min-w-4 text-[9px]"
            />
          </Button>
          <Sheet open={mobileNavOpen} onOpenChange={setMobileNavOpen}>
            <SheetTrigger
              render={
                <Button
                  type="button"
                  variant="ghost"
                  size="icon"
                  className="text-muted-foreground shrink-0"
                  aria-label="Mở menu"
                />
              }
            >
              <Menu className="size-5" />
            </SheetTrigger>
            <SheetContent side="right" className="w-[min(100vw,20rem)]">
              <SheetHeader>
                <SheetTitle>Menu</SheetTitle>
              </SheetHeader>
              <nav className="flex flex-col gap-1 mt-6 px-2">
                {nav.map((item) => {
                  const Icon = item.icon;
                  const isActive =
                    pathname === item.href ||
                    (item.href !== "/" &&
                      pathname.startsWith(`${item.href}/`));
                  return (
                    <Link
                      key={item.href}
                      href={item.href}
                      onClick={() => setMobileNavOpen(false)}
                      className={`flex items-center gap-3 rounded-xl px-3 py-3 text-sm font-bold transition-colors ${isActive ? "bg-primary/10 text-primary" : "text-foreground hover:bg-muted"}`}
                    >
                      <Icon className="size-4 shrink-0 opacity-80" />
                      {item.label}
                    </Link>
                  );
                })}
                {session ? (
                  <>
                    <div className="my-3 border-t border-border" />
                    <Link
                      href="/store/orders"
                      onClick={() => setMobileNavOpen(false)}
                      className={`flex items-center gap-3 rounded-xl px-3 py-3 text-sm font-bold transition-colors ${pathname.startsWith("/store/orders") ? "bg-primary/10 text-primary" : "text-foreground hover:bg-muted"}`}
                    >
                      <Package className="size-4 shrink-0 opacity-80" />
                      Đơn hàng
                    </Link>
                    <Link
                      href={profileHref}
                      onClick={() => setMobileNavOpen(false)}
                      className={`flex items-center gap-3 rounded-xl px-3 py-3 text-sm font-bold transition-colors ${pathname.startsWith("/store/profile") ? "bg-primary/10 text-primary" : "text-foreground hover:bg-muted"}`}
                    >
                      <User className="size-4 shrink-0 opacity-80" />
                      Trang cá nhân
                    </Link>
                    <button
                      type="button"
                      onClick={() => {
                        setMobileNavOpen(false);
                        handleLogout();
                      }}
                      className="flex w-full items-center gap-3 rounded-xl px-3 py-3 text-sm font-bold text-destructive transition-colors hover:bg-destructive/10"
                    >
                      <LogOut className="size-4 shrink-0 opacity-80" />
                      Đăng xuất
                    </button>
                  </>
                ) : null}
                <div className="my-3 border-t border-border" />
                <div className="flex items-center justify-between gap-2 px-1 py-2">
                  <Text as="span" variant="label" className="text-muted-foreground text-xs">Giao diện</Text>
                  <div className="flex items-center gap-1">
                    <TextSizeToggle />
                    <ThemeToggle />
                  </div>
                </div>
              </nav>
            </SheetContent>
          </Sheet>
        </div>

        {/* Nav desktop */}
        <nav className="ml-auto hidden md:flex items-center gap-4">
          {nav.map((item) => {
            const isActive =
              pathname === item.href ||
              (item.href !== "/" && pathname.startsWith(`${item.href}/`));
            return (
              <Link
                key={item.href}
                href={item.href}
                className={
                  "relative flex items-center gap-1.5 px-1 py-1 transition-all duration-200 " +
                  (isActive
                    ? "text-primary font-semibold"
                    : "text-muted-foreground hover:text-primary")
                }
              >
                <Text as="span" variant="label" className="font-bold">{item.label}</Text>
                {isActive && (
                  <span className="absolute -bottom-[21px] left-0 right-0 h-0.5 bg-primary rounded-full" />
                )}
              </Link>
            );
          })}

          <Separator orientation="vertical" className="mx-2 h-6 bg-outline-variant/50" />

          <div className="flex items-center gap-1">
            <Button
              type="button"
              variant="ghost"
              size="icon"
              onClick={openCart}
              aria-label={
                itemCount > 0 ? `Giỏ hàng, ${itemCount} loại` : "Giỏ hàng"
              }
              className="relative inline-flex size-9 items-center justify-center rounded-lg text-muted-foreground transition-colors hover:bg-muted hover:text-primary"
            >
              <ShoppingCart className="size-5" />
              <CartCountBadge
                count={itemCount}
                className="-right-1 -top-1 h-5 min-w-5 text-[10px]"
              />
            </Button>
            <Button variant="ghost" size="icon" className="text-muted-foreground hover:text-primary">
              <Bell className="size-5" />
            </Button>
            {session ? (
              <DropdownMenu>
                <DropdownMenuTrigger
                  className="flex items-center gap-2 rounded-lg px-2 py-1.5 hover:bg-muted transition-colors"
                >
                  {session.role === "admin" ? (
                    <ShieldCheck className="size-5 text-primary" />
                  ) : (
                    <UserCircle className="size-5 text-primary" />
                  )}
                  <span className="text-xs font-semibold text-foreground max-w-28 truncate">
                    {session.displayName}
                  </span>
                  <ChevronDown className="size-3.5 text-muted-foreground" />
                </DropdownMenuTrigger>
                <DropdownMenuContent align="end" className="w-56">
                  <DropdownMenuGroup>
                    <DropdownMenuLabel>Tài khoản</DropdownMenuLabel>
                    <DropdownMenuItem onClick={() => router.push("/store/orders")}>
                      <Package className="size-4" />
                      Đơn hàng
                    </DropdownMenuItem>
                    <DropdownMenuItem onClick={() => router.push(profileHref)}>
                      <User className="size-4" />
                      Trang cá nhân
                    </DropdownMenuItem>
                  </DropdownMenuGroup>
                  <DropdownMenuSeparator />
                  <DropdownMenuItem variant="destructive" onClick={handleLogout}>
                    <LogOut className="size-4" />
                    Đăng xuất
                  </DropdownMenuItem>
                </DropdownMenuContent>
              </DropdownMenu>
            ) : (
              <Link href="/login">
                <Button variant="ghost" size="icon" className="text-muted-foreground hover:text-primary">
                  <UserCircle className="size-5" />
                </Button>
              </Link>
            )}
          </div>

          <Separator orientation="vertical" className="mx-2 h-6 bg-outline-variant/50" />

          <div className="flex items-center gap-2">
            <TextSizeToggle />
            <ThemeToggle />
          </div>
        </nav>
      </div>
    </header>
  );
}

src/components/shared/order-status-table.content:
import Link from "next/link";
import {
  ArrowRight,
  CircleCheckBig,
  OctagonX,
  Truck,
} from "lucide-react";
import { Card, CardContent } from "@ui/components/card";
import { Button } from "@ui/components/button";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@ui/components/table";
import { StoreOrderRowStatusBadge } from "@ui/components/product";

export type OrderStatusTableRow = {
  /** Khóa React (vd. id số đơn); hiển thị mã đơn ở cột đầu dùng `orderCode`. */
  rowKey: string;
  orderCode: string;
  date: string;
  statusText: string;
  etaOrTotal: string;
  status: "shipping" | "completed" | "cancelled";
  href: string;
  ctaLabel: string;
};

export function OrderStatusTable({ rows }: { rows: OrderStatusTableRow[] }) {
  return (
    <Card className="border-border py-0 overflow-hidden">
      <CardContent className="p-0 overflow-x-auto">
        <Table>
          <TableHeader>
            <TableRow className="bg-muted/30">
              <TableHead className="pl-6">Mã đơn</TableHead>
              <TableHead>Ngày đặt</TableHead>
              <TableHead>Trạng thái</TableHead>
              <TableHead>Thông tin</TableHead>
              <TableHead className="text-right pr-6">Hành động</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {rows.map((row) => (
              <TableRow key={row.rowKey}>
                <TableCell className="pl-6 font-bold">{row.orderCode}</TableCell>
                <TableCell className="text-muted-foreground">{row.date}</TableCell>
                <TableCell>
                  <StoreOrderRowStatusBadge
                    status={row.status}
                    icon={
                      row.status === "shipping"
                        ? Truck
                        : row.status === "completed"
                          ? CircleCheckBig
                          : OctagonX
                    }
                  >
                    {row.statusText}
                  </StoreOrderRowStatusBadge>
                </TableCell>
                <TableCell className="text-muted-foreground">{row.etaOrTotal}</TableCell>
                <TableCell className="text-right pr-6">
                  <Link href={row.href}>
                    <Button variant="outline" size="sm">
                      {row.ctaLabel}
                      <ArrowRight className="w-4 h-4 ml-1.5" />
                    </Button>
                  </Link>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </CardContent>
    </Card>
  );
}

src/components/shared/product-card.tsx.content:
"use client";

import Link from "next/link";
import { ArrowRight, Plus, ShoppingCart, Tag } from "lucide-react";
import { Card, CardContent, CardFooter } from "@ui/components/card";
import { Badge } from "@ui/components/badge";
import { Button } from "@ui/components/button";
import { Heading, Text } from "@ui/components/typography";
import { cn } from "@ui/lib/utils";

type ProductCardVariant = "catalog" | "flash";

type ProductCardProps = {
  variant: ProductCardVariant;
  href: string;
  name: string;
  image: string;
  price: string;
  originalPrice?: string;
  category?: string;
  minQty?: string;
  coupon?: string;
  discountLabel?: string;
  soldText?: string;
  progressPercent?: number;
  topRightBadge?: string;
  primaryCtaLabel?: string;
  onAddToCart?: () => void;
};

export function ProductCard({
  variant,
  href,
  name,
  image,
  price,
  originalPrice,
  category,
  minQty,
  coupon,
  discountLabel,
  soldText,
  progressPercent,
  topRightBadge = "Chính hãng",
  primaryCtaLabel = "Xem chi tiết",
  onAddToCart,
}: ProductCardProps) {
  const isFlash = variant === "flash";

  return (
    <Card
      className={cn(
        "group overflow-hidden rounded-2xl border-outline-variant/80 bg-background py-0 transition-all duration-300 hover:border-primary/25 hover:shadow-lg",
        isFlash && "shadow-sm",
      )}
    >
      <Link
        href={href}
        className={cn(
          "relative block bg-gradient-to-b from-white to-muted/15",
          isFlash ? "h-44 md:h-48" : "h-64 w-full",
        )}
      >
        <div className="flex h-full items-center justify-center overflow-hidden border-b border-outline-variant/20 bg-white/70">
          <img
            src={image}
            alt={name}
            className="h-full w-full object-cover transition-transform duration-500 group-hover:scale-105"
          />
        </div>

        <div className="absolute right-2 top-2">
          <Badge variant="overlay" size="sm" className="px-2 py-0.5 text-[10px] shadow-sm">
            {topRightBadge}
          </Badge>
        </div>

        {coupon && variant === "catalog" && (
          <div className="absolute left-4 top-4 flex items-center gap-1.5 rounded-xl border border-warning/30 bg-warning/20 px-3 py-1.5 text-sm font-bold text-warning-foreground shadow-sm backdrop-blur-sm">
            <Tag className="size-4" />
            {coupon}
          </div>
        )}

        {discountLabel && isFlash && (
          <div className="absolute left-2 top-2 rounded-lg bg-destructive px-2 py-1 text-xs font-black text-white shadow-md">
            {discountLabel}
          </div>
        )}
      </Link>

      <CardContent
        className={cn(
          "flex flex-col",
          isFlash ? "gap-2 p-3.5 pb-2" : "h-[260px] space-y-4 p-6",
        )}
      >
        {category && (
          <div className="text-sm font-bold uppercase tracking-widest text-primary/80">
            {category}
          </div>
        )}

        <Link href={href} className="group/title">
          {isFlash ? (
            <p className="line-clamp-2 text-sm font-bold leading-snug text-foreground transition-colors group-hover/title:text-primary md:text-[15px]">
              {name}
            </p>
          ) : (
            <Heading
              as="h3"
              size="title"
              className="line-clamp-2 min-h-[4rem] leading-tight transition-colors group-hover/title:text-primary"
            >
              {name}
            </Heading>
          )}
        </Link>

        <div
          className={cn(
            "mt-auto space-y-2",
            !isFlash && "border-t border-outline-variant/30 pt-4",
          )}
        >
          <div className="flex flex-wrap items-baseline gap-x-2 gap-y-0.5">
            {originalPrice && (
              <Text
                variant="muted"
                className={cn(
                  "shrink-0 font-medium line-through",
                  isFlash ? "text-xs" : "text-sm",
                )}
              >
                {originalPrice}
              </Text>
            )}
            {isFlash ? (
              <span className="text-lg font-black tabular-nums text-primary">
                {price}
              </span>
            ) : (
              <Heading as="span" size="title" color="primary" className="shrink-0">
                {price}
              </Heading>
            )}
          </div>

          {variant === "catalog" && minQty && (
            <div className="mt-1 flex items-center gap-1 text-base font-bold text-primary">
              <Plus className="size-4" />
              {minQty}
            </div>
          )}

          {isFlash && soldText && (
            <div className="space-y-1.5">
              <div className="flex items-center justify-between gap-2 text-[11px] font-semibold">
                <Text as="span" variant="muted" className="truncate">
                  {soldText}
                </Text>
                <span className="shrink-0 rounded-full bg-primary/10 px-1.5 py-0.5 text-[10px] font-bold text-primary">
                  Hot
                </span>
              </div>
              <div className="h-1.5 overflow-hidden rounded-full bg-muted">
                <div
                  className="h-full rounded-full bg-gradient-to-r from-primary to-teal-500 transition-[width] duration-500"
                  style={{
                    width: `${Math.max(0, Math.min(100, progressPercent ?? 0))}%`,
                  }}
                />
              </div>
            </div>
          )}
        </div>
      </CardContent>

      <CardFooter className={isFlash ? "px-3.5 pb-3.5 pt-0" : undefined}>
        <div
          className={cn(
            "flex w-full",
            variant === "catalog" ? "items-center gap-2" : "",
          )}
        >
          <Link href={href} className={variant === "catalog" ? "flex-1" : "w-full"}>
            <Button
              size={isFlash ? "sm" : "lg"}
              className={cn(
                "w-full gap-1.5 font-bold shadow-md transition-all hover:bg-primary/90",
                isFlash
                  ? "h-9 rounded-xl text-xs md:text-sm"
                  : "h-14 rounded-2xl text-lg shadow-lg",
              )}
            >
              <ArrowRight className={isFlash ? "size-3.5" : "size-5"} />
              {primaryCtaLabel}
            </Button>
          </Link>
          {variant === "catalog" && onAddToCart && (
            <Button
              className="h-14 w-14 rounded-2xl shadow-lg transition-all hover:scale-110 hover:bg-primary/90"
              aria-label="Thêm vào giỏ"
              onClick={onAddToCart}
            >
              <ShoppingCart className="size-7" />
            </Button>
          )}
        </div>
      </CardFooter>
    </Card>
  );
}

