"use client";

import { useEffect, useMemo, useState } from "react";
import Link from "next/link";
import {
  ArrowLeft,
  ShoppingCart,
  Truck,
  AlertTriangle,
  CheckCircle2,
} from "lucide-react";
import { Button } from "@ui/components/button";
import { toast } from "sonner";
import {
  ProductDetailActions,
  ProductDetailCallout,
  ProductDetailGallery,
  ProductDetailInfoHeader,
  ProductDetailLayout,
  ProductDetailMetaGrid,
  ProductDetailOrderRow,
  ProductDetailPromoGiftsSection,
  hasUnitWholesalePromo,
  ProductDetailPurchaseCard,
  ProductDetailPurchaseCardSection,
  ProductDetailUnitPicker,
  formatProductVnd,
} from "@ui/components/product";
import type { Product, ProductUnitType } from "@/lib/api";
import { unitSellingAndListPrice } from "@workspace/api-client";
import { getProductUnits } from "@/lib/catalog-filters";
import {
  cartReservedBase,
  clampSellQty,
  productBaseStock,
  remainingUnitStock,
  unitStock,
} from "@workspace/api-client";
import { cartLineQuantity, useCart } from "@/hooks/use-cart";
import { useGiftProductCatalogMap } from "@/hooks/use-gift-product-catalog";
import { resolveGiftRulesForUnit } from "@workspace/api-client";
import { ProductSuggestions } from "@/components/shared/product-suggestions";

type ProductDetailProps = {
  product: Product;
  backHref?: string;
  supportHref?: string;
};

function resolveDisplayImages(unit: ProductUnitType, product: Product) {
  const own = (unit.images ?? []).filter((url) => url.trim().length > 0);
  if (own.length > 0) return own;
  return (product.images ?? []).filter((url) => url.trim().length > 0);
}

export function ProductDetail({
  product,
  backHref = "/catalog",
  supportHref = "/support",
}: ProductDetailProps) {
  const categoryLabel =
    product.category.replace(/-/g, " ").replace(/\b\w/g, (c) => c.toUpperCase()) ||
    product.category;
  const cart = useCart();
  const fallbackUnit: ProductUnitType = useMemo(
    () => ({
      type: product.unit,
      label: product.unit,
      wholesalePrice: product.wholesalePrice,
      retailPrice: product.retailPrice,
      minWholesaleQty: 1,
      qtyPerUnit: 1,
      images: product.images ?? undefined,
    }),
    [product],
  );
  const units: ProductUnitType[] = (() => {
    const parsed = getProductUnits(product);
    return parsed.length > 0 ? parsed : [fallbackUnit];
  })();

  const [selectedUnit, setSelectedUnit] = useState<ProductUnitType>(units[0]!);
  const displayImages = useMemo(
    () => resolveDisplayImages(selectedUnit, product),
    [selectedUnit, product],
  );

  const baseStock = productBaseStock(product);
  const reservedBase = cartReservedBase(cart.lines, product.id);
  const unitStockCount = unitStock(selectedUnit, product);
  const qtyInCart = cartLineQuantity(
    cart.lines,
    product.id,
    selectedUnit.type,
  );
  const availableQty = remainingUnitStock(
    selectedUnit,
    product,
    reservedBase,
  );
  const maxQty = availableQty;
  const minPurchaseQty = availableQty > 0 ? 1 : 0;
  const [qty, setQty] = useState(availableQty > 0 ? 1 : 0);

  useEffect(() => {
    setQty((current) => {
      if (availableQty <= 0) return 0;
      return Math.max(1, Math.min(current || 1, availableQty));
    });
  }, [availableQty, selectedUnit.type]);
  const pricingQty = qtyInCart + qty;
  const productSellQty = useMemo(() => {
    const fromCart = cart.lines
      .filter((line) => line.productId === product.id)
      .reduce((sum, line) => sum + line.quantity, 0);
    return fromCart + qty;
  }, [cart.lines, product.id, qty]);
  const giftRules = useMemo(
    () => resolveGiftRulesForUnit(selectedUnit, product.fulfillmentNote),
    [selectedUnit, product.fulfillmentNote],
  );
  const { data: giftCatalogMap } = useGiftProductCatalogMap(giftRules);
  const giftHrefForRule = useMemo(
    () => (rule: (typeof giftRules)[number]) => giftCatalogMap?.get(rule.id),
    [giftCatalogMap],
  );

  const isWholesale = hasUnitWholesalePromo(selectedUnit);
  const showPromoGiftsSection = isWholesale || giftRules.length > 0;
  const { current: unitPrice, list: listPrice } = unitSellingAndListPrice(
    selectedUnit,
    pricingQty,
  );

  const totalUnits = qty * Math.max(selectedUnit.qtyPerUnit, 1);
  const totalPrice = unitPrice * qty;
  const stockWarning = availableQty > 0 && qty > availableQty * 0.8;
  const outOfStock = availableQty <= 0;

  const clampQty = (value: number) =>
    clampSellQty(value, minPurchaseQty, availableQty);

  const handleUnitChange = (type: string) => {
    const next = units.find((unit) => unit.type === type);
    if (!next) return;
    setSelectedUnit(next);
    const nextReserved = cartReservedBase(cart.lines, product.id);
    const nextAvailable = remainingUnitStock(next, product, nextReserved);
    setQty(nextAvailable > 0 ? 1 : 0);
  };

  const handleAddToCart = () => {
    const safeQty = clampQty(qty);
    if (outOfStock || safeQty <= 0 || safeQty > availableQty) {
      if (!outOfStock && safeQty > availableQty) {
        toast.error(`Chỉ còn ${availableQty} ${selectedUnit.type} trong kho`);
        setQty(clampQty(safeQty));
      }
      return;
    }
    const result = cart.add(product, selectedUnit, safeQty);
    if (!result.ok) {
      toast.error(
        result.reason === "out_of_stock"
          ? `Chỉ còn ${availableQty} ${selectedUnit.type} trong kho`
          : "Số lượng không hợp lệ",
      );
      return;
    }
    toast.success(
      `Đã thêm ${result.added} ${selectedUnit.label} vào giỏ hàng`,
      {
        description: `${product.name} · Tổng: ${formatProductVnd(unitPrice * result.added)}`,
      },
    );
  };

  const unitOptions = units.map((unit) => {
    const inCartU = cartLineQuantity(cart.lines, product.id, unit.type);
    const previewQty = inCartU + qty;
    const { current, list } = unitSellingAndListPrice(unit, previewQty);
    return {
      type: unit.type,
      label: unit.label,
      currentPriceLabel: formatProductVnd(current),
      listPriceLabel: list != null ? formatProductVnd(list) : null,
      hasPromo: hasUnitWholesalePromo(unit),
    };
  });

  return (
    <>
      <Link href={backHref}>
        <Button variant="outline" className="rounded-xl">
          <ArrowLeft className="mr-2 size-4" /> Quay lại danh mục
        </Button>
      </Link>

      <div className="space-y-8">
      <ProductDetailLayout
        gallery={
          <ProductDetailGallery images={displayImages} alt={product.name} />
        }
        details={
          <>
            <ProductDetailInfoHeader
              categoryLabel={categoryLabel}
              title={product.name}
              description={product.description}
              couponBadges={product.coupons ?? []}
            />

            <ProductDetailPurchaseCard>
              {units.length > 1 ? (
                <ProductDetailPurchaseCardSection>
                  <ProductDetailUnitPicker
                    options={unitOptions}
                    selectedType={selectedUnit.type}
                    onSelect={handleUnitChange}
                    showPrice={false}
                    layout="chips"
                    showLabel={false}
                  />
                </ProductDetailPurchaseCardSection>
              ) : null}

              <ProductDetailPurchaseCardSection variant="order">
                <ProductDetailOrderRow
                  unitPrice={unitPrice}
                  listPrice={listPrice}
                  unitLabel={selectedUnit.label}
                  hasWholesale={isWholesale}
                  qty={qty}
                  unitType={selectedUnit.type}
                  onQtyChange={(next) => setQty(clampQty(next))}
                  minQty={minPurchaseQty}
                  maxQty={maxQty}
                  equivalentTotal={totalUnits}
                  equivalentUnit={product.unit}
                  stockCount={unitStockCount}
                  stockStatus={
                    outOfStock ? "out" : stockWarning ? "low" : "ok"
                  }
                  footer={
                    <p className="text-[11px] text-muted-foreground">
                      {qtyInCart > 0 ? (
                        <>
                          Trong giỏ{" "}
                          <span className="font-semibold text-foreground">
                            {qtyInCart}
                          </span>
                          {" / tồn "}
                          <span className="font-semibold text-foreground">
                            {unitStockCount}
                          </span>
                          {" · còn thêm "}
                          <span className="font-semibold text-primary">
                            {availableQty}
                          </span>
                          {" + đặt "}
                          <span className="font-semibold text-foreground">
                            {qty}
                          </span>
                          {" → áp giá "}
                          <span className="font-semibold text-primary">
                            {pricingQty}
                          </span>
                        </>
                      ) : (
                        <>
                          Tối đa{" "}
                          <span className="font-semibold text-foreground">
                            {availableQty}
                          </span>{" "}
                          {selectedUnit.type} (pool{" "}
                          <span className="font-semibold text-foreground tabular-nums">
                            {baseStock}
                          </span>{" "}
                          {product.unit})
                        </>
                      )}
                    </p>
                  }
                />
              </ProductDetailPurchaseCardSection>

              {showPromoGiftsSection ? (
                <ProductDetailPurchaseCardSection variant="muted">
                  <ProductDetailPromoGiftsSection
                    unit={selectedUnit}
                    giftRules={giftRules}
                    pricingQty={pricingQty}
                    productSellQty={productSellQty}
                    giftHrefForRule={giftHrefForRule}
                  />
                </ProductDetailPurchaseCardSection>
              ) : null}
            </ProductDetailPurchaseCard>

            {(stockWarning || outOfStock) ? (
              <ProductDetailCallout
                tone="warning"
                icon={AlertTriangle}
                title={
                  outOfStock
                    ? qtyInCart > 0
                      ? "Đã đạt tồn kho trong giỏ"
                      : "Hết hàng"
                    : "Sắp hết hàng"
                }
              />
            ) : null}

            <ProductDetailMetaGrid
              compact
              items={[
                { label: "Thương hiệu", value: product.brand ?? "—" },
                { label: "Xuất xứ", value: product.origin ?? "—" },
                { label: "SKU", value: product.sku },
              ]}
            />

            <ProductDetailActions
              primary={
                <Button
                  className="h-11 w-full rounded-xl px-6 text-sm font-black shadow-sm"
                  onClick={handleAddToCart}
                  disabled={outOfStock}
                >
                  <ShoppingCart className="mr-2 size-4" />
                  {outOfStock
                    ? "Hết hàng"
                    : `Thêm vào giỏ – ${formatProductVnd(totalPrice)}`}
                </Button>
              }
              secondary={
                <Link href={supportHref} className="block h-full">
                  <Button
                    variant="outline"
                    className="h-11 w-full rounded-xl px-5 text-sm font-semibold sm:min-w-[7.5rem]"
                  >
                    <Truck className="mr-1.5 size-3.5" /> Tư vấn
                  </Button>
                </Link>
              }
              trust={
                !outOfStock ? (
                  <p className="flex items-center gap-1.5 text-xs font-medium text-success">
                    <CheckCircle2 className="size-3.5 shrink-0" />
                    Còn hàng · Giao hôm nay hoặc ngày mai
                  </p>
                ) : null
              }
            />
          </>
        }
      />

      <ProductSuggestions productId={product.id} category={product.category} />
      </div>
    </>
  );
}

src/components/shared/product-suggestion.content:
"use client";

import Link from "next/link";
import { ArrowRight, Package2, Sparkles, Tag } from "lucide-react";
import { ProductDiscountBadge } from "@ui/components/product";
import { Badge } from "@ui/components/badge";
import { formatProductVnd, hasUnitWholesalePromo } from "@ui/components/product";
import type { Product } from "@/lib/api";
import { getProductUnits } from "@/lib/catalog-filters";
import { unitSellingAndListPrice } from "@workspace/api-client";
import { useSuggestedProducts } from "@/hooks/queries";

type ProductSuggestionsProps = {
  productId: number;
  category: string;
};

function formatCategoryLabel(category: string) {
  return (
    category.replace(/-/g, " ").replace(/\b\w/g, (c) => c.toUpperCase()) ||
    category
  );
}

function SuggestionCard({ product }: { product: Product }) {
  const units = getProductUnits(product);
  const unit = units[0];
  const { current, list } = unit
    ? unitSellingAndListPrice(unit, 1)
    : { current: product.retailPrice, list: null as number | null };
  const image = product.images?.[0];
  const categoryLabel = formatCategoryLabel(product.category);
  const meta = [product.brand, product.origin].filter(Boolean).join(" · ");
  const firstCoupon = product.coupons?.[0];
  const hasPromo = unit ? hasUnitWholesalePromo(unit) : false;
  const discountPercent =
    list != null && list > current
      ? Math.round(((list - current) / list) * 100)
      : 0;

  return (
    <Link
      href={`/catalog/${product.id}`}
      className="group/card flex h-full min-w-[10.5rem] shrink-0 snap-start flex-col overflow-hidden rounded-3xl border border-outline-variant/35 bg-background shadow-sm transition-all duration-300 hover:-translate-y-0.5 hover:border-primary/25 hover:shadow-lg sm:min-w-[12.5rem] lg:min-w-0"
    >
      <div className="relative aspect-square overflow-hidden bg-gradient-to-b from-white to-muted/25">
        {image ? (
          <img
            src={image}
            alt={product.name}
            className="size-full object-cover transition-transform duration-500 group-hover/card:scale-[1.04]"
          />
        ) : (
          <div className="flex size-full items-center justify-center">
            <Package2 className="size-10 text-outline-variant" aria-hidden />
          </div>
        )}

        <div className="pointer-events-none absolute inset-0 bg-gradient-to-t from-black/35 via-transparent to-transparent opacity-0 transition-opacity duration-300 group-hover/card:opacity-100" />

        {firstCoupon ? (
          <Badge
            variant="coupon"
            size="xs"
            shape="pill"
            className="absolute top-2.5 left-2.5 max-w-[72%] truncate shadow-sm"
          >
            <Tag aria-hidden />
            {firstCoupon}
          </Badge>
        ) : null}

        {hasPromo && discountPercent > 0 ? (
          <ProductDiscountBadge
            percent={discountPercent}
            className="absolute top-2.5 right-2.5 shadow-sm"
          />
        ) : (
          <Badge
            variant="overlay"
            size="xs"
            className="absolute top-2.5 right-2.5 max-w-[70%] truncate"
          >
            {categoryLabel}
          </Badge>
        )}

        <span className="absolute inset-x-0 bottom-3 flex justify-center opacity-0 transition-all duration-300 group-hover/card:translate-y-0 group-hover/card:opacity-100 translate-y-1">
          <span className="inline-flex items-center gap-1 rounded-full bg-background/95 px-3 py-1 text-xs font-bold text-foreground shadow-md backdrop-blur-sm">
            Xem chi tiết
            <ArrowRight className="size-3.5" aria-hidden />
          </span>
        </span>
      </div>

      <div className="flex flex-1 flex-col gap-2.5 p-4">
        <p className="text-[11px] font-bold uppercase tracking-widest text-primary/75">
          {categoryLabel}
        </p>

        <p className="line-clamp-2 min-h-[2.5rem] text-sm font-bold leading-snug text-foreground transition-colors group-hover/card:text-primary sm:text-base">
          {product.name}
        </p>

        {meta ? (
          <p className="line-clamp-1 text-xs font-medium text-muted-foreground">
            {meta}
          </p>
        ) : null}

        <div className="mt-auto space-y-1 border-t border-outline-variant/25 pt-3">
          <div className="flex flex-wrap items-baseline gap-2">
            {list != null ? (
              <span className="text-xs font-semibold text-muted-foreground line-through sm:text-sm">
                {formatProductVnd(list)}
              </span>
            ) : null}
            <span className="text-lg font-black text-primary sm:text-xl">
              {formatProductVnd(current)}
            </span>
          </div>
          {unit ? (
            <p className="text-[11px] font-medium text-muted-foreground">
              / {unit.label}
              {hasPromo ? (
                <span className="ml-1 font-semibold text-primary">· Có KM</span>
              ) : null}
            </p>
          ) : null}
        </div>
      </div>
    </Link>
  );
}

function SuggestionsSkeleton() {
  return (
    <div className="-mx-1 flex gap-3 overflow-hidden px-1 pb-1 sm:gap-4 lg:mx-0 lg:grid lg:grid-cols-4 lg:overflow-visible lg:px-0">
      {Array.from({ length: 4 }).map((_, index) => (
        <div
          key={index}
          className="min-w-[10.5rem] shrink-0 overflow-hidden rounded-3xl border border-outline-variant/30 sm:min-w-[12.5rem] lg:min-w-0"
        >
          <div className="aspect-square animate-pulse bg-muted/40" />
          <div className="space-y-2.5 p-4">
            <div className="h-3 w-16 animate-pulse rounded bg-muted/40" />
            <div className="h-4 animate-pulse rounded bg-muted/40" />
            <div className="h-4 w-[80%] animate-pulse rounded bg-muted/40" />
            <div className="h-6 w-24 animate-pulse rounded bg-muted/40" />
          </div>
        </div>
      ))}
    </div>
  );
}

export function ProductSuggestions({
  productId,
  category,
}: ProductSuggestionsProps) {
  const { data, isLoading } = useSuggestedProducts(productId, category);
  const categoryLabel = formatCategoryLabel(category);
  const catalogHref =
    category.trim().length > 0
      ? `/catalog?cat=${encodeURIComponent(category.trim())}`
      : "/catalog";

  if (!isLoading && (!data || data.length === 0)) return null;

  return (
    <section
      className="overflow-hidden rounded-2xl border border-outline-variant/30 bg-card shadow-md ring-1 ring-black/[0.03] dark:ring-white/[0.04]"
      aria-labelledby="product-suggestions-heading"
    >
      <div className="border-b border-outline-variant/25 bg-gradient-to-r from-primary/[0.06] via-background to-muted/20 px-4 py-4 sm:px-6 sm:py-5">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <div className="space-y-1">
            <p className="flex items-center gap-1.5 text-xs font-bold uppercase tracking-widest text-primary">
              <Sparkles className="size-3.5 shrink-0" aria-hidden />
              Mua kèm
            </p>
            <h2
              id="product-suggestions-heading"
              className="text-lg font-black text-foreground sm:text-xl"
            >
              Sản phẩm gợi ý
            </h2>
            <p className="text-sm text-muted-foreground">
              Cùng nhóm {categoryLabel} và các mặt hàng hay đặt chung
            </p>
          </div>

          <Link
            href={catalogHref}
            className="inline-flex items-center gap-1 rounded-xl border border-primary/20 bg-primary/5 px-3 py-2 text-sm font-bold text-primary transition-colors hover:bg-primary/10"
          >
            Xem danh mục
            <ArrowRight className="size-4" aria-hidden />
          </Link>
        </div>
      </div>

      <div className="p-4 sm:p-6">
        {isLoading ? (
          <SuggestionsSkeleton />
        ) : (
          <div className="-mx-1 flex gap-3 overflow-x-auto px-1 pb-1 [-ms-overflow-style:none] [scrollbar-width:none] sm:gap-4 lg:mx-0 lg:grid lg:grid-cols-4 lg:overflow-visible lg:px-0 [&::-webkit-scrollbar]:hidden">
            {data!.map((item) => (
              <SuggestionCard key={item.id} product={item} />
            ))}
          </div>
        )}
      </div>
    </section>
  );
}

src/components/shared/product-wide-card..content:
"use client";

import Link from "next/link";
import { Star } from "lucide-react";
import { Text } from "@ui/components/typography";
import { Badge } from "@ui/components/badge";
import { cn } from "@ui/lib/utils";

type ProductWideCardProps = {
  productId: string;
  name: string;
  /** Giá đang bán (ưu đãi) */
  price: string;
  /** Giá ban đầu — gạch ngang khi có giá khuyến mãi thấp hơn */
  listPrice?: string;
  sold: string;
  image: string;
  tag: string;
  category?: string;
};

export function ProductWideCard({
  productId,
  name,
  price,
  listPrice,
  sold,
  image,
  tag,
  category,
}: ProductWideCardProps) {
  return (
    <Link href={`/catalog/${productId}`} className="block h-full">
      <div
        className={cn(
          "group flex h-full cursor-pointer items-center gap-3 rounded-2xl border border-outline-variant/80",
          "bg-background p-3 transition-all duration-300 hover:border-primary/30 hover:shadow-md md:gap-4 md:p-3.5",
        )}
      >
        <div className="relative size-20 shrink-0 overflow-hidden rounded-xl border border-outline-variant/30 bg-gradient-to-b from-white to-muted/20 md:size-24">
          <img
            src={image}
            alt={name}
            className="size-full object-cover transition-transform duration-500 group-hover:scale-105"
          />
          <span className="absolute left-1 top-1 max-w-[calc(100%-0.5rem)] truncate rounded-md bg-primary px-1.5 py-0.5 text-[9px] font-black uppercase tracking-wide text-primary-foreground shadow-sm md:text-[10px]">
            {tag}
          </span>
        </div>

        <div className="flex min-w-0 flex-1 flex-col justify-center gap-1.5">
          {category && (
            <Text
              variant="caption"
              className="truncate text-[10px] font-bold uppercase tracking-wider text-primary/80 md:text-[11px]"
            >
              {category}
            </Text>
          )}

          <p className="line-clamp-2 text-sm font-bold leading-snug text-foreground transition-colors group-hover:text-primary md:text-[15px]">
            {name}
          </p>

          <div className="flex flex-wrap items-center gap-x-2 gap-y-1">
            {listPrice && (
              <Text as="span" variant="muted" className="text-xs font-medium line-through">
                {listPrice}
              </Text>
            )}
            <span className="text-sm font-black tabular-nums text-primary md:text-base">
              {price}
            </span>
            <Badge variant="success" size="sm" className="h-5 px-1.5 text-[10px]">
              Bán chạy
            </Badge>
          </div>

          <Text
            variant="small"
            className="flex items-center gap-1 text-[11px] font-semibold uppercase tracking-wide text-muted-foreground"
          >
            <Star className="size-3.5 shrink-0 fill-yellow-400 text-yellow-400" />
            <span className="truncate">{sold} đã nhập</span>
          </Text>
        </div>
      </div>
    </Link>
  );
}

