    "Tài khoản không có quyền quản trị cửa hàng B2B.",
}

export function SignInForm() {
  const clientReady = useClientReady()

  return (
    <AdminSignInForm
      config={STORE_ADMIN_SIGN_IN_CONFIG}
      loginLock={clientReady ? { ok: true as const } : { ok: true as const }}
    />
  )
}

