"use client";

import { useSyncExternalStore } from "react";

const noopSubscribe = () => () => {};

/**
 * `false` khi render trên server / trước hydrate, `true` trên client.
 * Dùng thay vì `useEffect` + `setState` để tránh cảnh báo ESLint.
 */
export function useClientReady(): boolean {
  return useSyncExternalStore(noopSubscribe, () => true, () => false);
}

src/hooks/use-debounced-value.ts.content:
"use client";

import { useEffect, useState } from "react";

/**
 * Trì hoãn cập nhật giá trị (tìm kiếm, sync URL) để giảm render / request.
 */
export function useDebouncedValue<T>(value: T, delayMs: number): T {
  const [debounced, setDebounced] = useState(value);

  useEffect(() => {
    const t = window.setTimeout(() => setDebounced(value), delayMs);
    return () => window.clearTimeout(t);
  }, [value, delayMs]);

  return debounced;
}

src/hooks/use-gift-product-catalog.ts.content:
"use client";

import { useCallback, useMemo } from "react";
import { useQuery } from "@tanstack/react-query";
import {
  buildGiftCatalogHrefMap,
  collectGiftCatalogLookups,
  type Product,
  type ProductGiftRule,
} from "@workspace/api-client";
import { api } from "@/lib/api";
import { giftRulesForCartLine } from "@/lib/cart-gift-rules";
import type { CartLine } from "@/hooks/use-cart";
import { useProducts } from "@/hooks/queries";

function indexActiveProducts(products: readonly Product[]): {
  byId: Map<number, Product>;
  bySku: Map<string, Product>;
} {
  const byId = new Map<number, Product>();
  const bySku = new Map<string, Product>();
  for (const product of products) {
    if (product.isActive === false) continue;
    byId.set(product.id, product);
    const sku = product.sku?.trim();
    if (sku) bySku.set(sku, product);
  }
  return { byId, bySku };
}

async function fetchMissingGiftProducts(
  lookup: ReturnType<typeof collectGiftCatalogLookups>,
  knownById: ReadonlyMap<number, Product>,
  knownBySku: ReadonlyMap<string, Product>,
): Promise<Product[]> {
  const missingIds = lookup.productIds.filter(
    (id: number) => !knownById.has(id),
  );
  const missingSkus = lookup.skus.filter(
    (sku: string) => !knownBySku.has(sku),
  );
  const fetched: Product[] = [];

  await Promise.all([
    ...missingIds.map(async (id: number) => {
      try {
        const product = await api.products.getPublic(id);
        fetched.push(product);
      } catch {
        /* SP đã ẩn / xóa — không link */
      }
    }),
    ...missingSkus.map(async (sku: string) => {
      const product = await api.products.bySkuPublic(sku);
      if (product) fetched.push(product);
    }),
  ]);

  return fetched;
}

export function useGiftProductCatalogMap(rules: readonly ProductGiftRule[]) {
  const lookup = useMemo(() => collectGiftCatalogLookups(rules), [rules]);
  const lookupKey = useMemo(
    () =>
      [
        ...lookup.productIds.sort((a, b) => a - b),
        ...lookup.skus.sort(),
      ].join("|"),
    [lookup],
  );
  const { data: catalogProducts } = useProducts();
  const catalogSeedKey = useMemo(
    () =>
      (catalogProducts ?? [])
        .map((p) => p.id)
        .sort((a: number, b: number) => a - b)
        .join(","),
    [catalogProducts],
  );

  return useQuery({
    queryKey: ["gift-product-catalog", lookupKey, catalogSeedKey] as const,
    queryFn: async () => {
      const seeded = indexActiveProducts(catalogProducts ?? []);
      const extra = await fetchMissingGiftProducts(
        lookup,
        seeded.byId,
        seeded.bySku,
      );
      const merged = indexActiveProducts([
        ...(catalogProducts ?? []),
        ...extra,
      ]);
      return buildGiftCatalogHrefMap(rules, merged.byId, merged.bySku);
    },
    enabled: lookupKey.length > 0,
    staleTime: 30_000,
    refetchOnWindowFocus: true,
  });
}

/** Resolver link quà theo rule — dùng chung cart page / checkout / drawer. */
export function useGiftHrefForRulesFromLines(lines: readonly CartLine[]) {
  const cartGiftRules = useMemo(
    () => lines.flatMap((line) => giftRulesForCartLine(line)),
    [lines],
  );
  const { data: giftCatalogMap } = useGiftProductCatalogMap(cartGiftRules);
  return useCallback(
    (rule: ProductGiftRule) => giftCatalogMap?.get(rule.id),
    [giftCatalogMap],
  );
}

src/hooks/use-graphify.ts.content:
"use client";

import { useState, useCallback } from "react";
import type { GraphifyPayload, GraphNode } from "@/lib/graphify-context";
import { getLinkedNodes, communityBreakdown, topHubs, routeFiles } from "@/lib/graphify-context";

export interface UseGraphifyReturn {
  data: GraphifyPayload | null;
  loading: boolean;
  error: string | null;
  selectedNode: GraphNode | null;
  setSelectedNode: (n: GraphNode | null) => void;
  linkedNodes: Map<string, number>;
  communities: ReturnType<typeof communityBreakdown>;
  hubs: ReturnType<typeof topHubs>;
  routes: ReturnType<typeof routeFiles>;
  refresh: () => Promise<void>;
}

export function useGraphify(maxDegree = 1): UseGraphifyReturn {
  const [data, setData] = useState<GraphifyPayload | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [selectedNode, setSelectedNode] = useState<GraphNode | null>(null);

  const refresh = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await fetch("/api/graphify");
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const payload: GraphifyPayload = await res.json();
      setData(payload);
    } catch (e) {
      setError(e instanceof Error ? e.message : "Unknown error");
    } finally {
      setLoading(false);
    }
  }, []);

  const linkedNodes = selectedNode && data
    ? getLinkedNodes(selectedNode.id, data.graph, maxDegree)
    : new Map<string, number>();

  return {
    data,
    loading,
    error,
    selectedNode,
    setSelectedNode,
    linkedNodes,
    communities: data ? communityBreakdown(data.graph) : [],
    hubs: data ? topHubs(data.context) : [],
    routes: data ? routeFiles(data.context) : [],
    refresh,
  };
}

src/hooks/use-mobile.ts.content:
import * as React from "react"

const MOBILE_BREAKPOINT = 768

export function useIsMobile() {
  const [isMobile, setIsMobile] = React.useState<boolean>(
    () => typeof window !== "undefined" && window.innerWidth < MOBILE_BREAKPOINT
  )

  React.useEffect(() => {
    const mql = window.matchMedia(`(max-width: ${MOBILE_BREAKPOINT - 1}px)`)
    const onChange = () => {
      setIsMobile(window.innerWidth < MOBILE_BREAKPOINT)
    }
    mql.addEventListener("change", onChange)
    return () => mql.removeEventListener("change", onChange)
  }, [])

  return isMobile
}

